<?php declare(strict_types=1); require __DIR__ . '/admin.php'; requireAdmin($database); $users = $database->query('SELECT id, name, email, role, created_at FROM users ORDER BY created_at DESC')->fetchAll(); adminHeader('Manage users'); ?><h1>Manage users</h1><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Created</th></tr><?php foreach ($users as $user): ?><tr><td><?= htmlspecialchars($user['name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($user['email'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($user['role'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($user['created_at'], ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?></table><?php adminFooter(); ?>
